const STORAGE_KEY='stsOperationsTrackerV1';
let store = loadStore(); let currentPage='Dashboard'; let searchText=''; let statusFilter='All statuses'; let selectedRecord=null; let detailBackPage='Dashboard';
function loadStore(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');const data={};Object.keys(CONFIG).forEach(k=>data[k]=Array.isArray(saved[k])?saved[k]:CONFIG[k].sample.map((r,i)=>({...r,_id:`${slug(k)}-${i+1}`})));return data}catch(e){const data={};Object.keys(CONFIG).forEach(k=>data[k]=CONFIG[k].sample.map((r,i)=>({...r,_id:`${slug(k)}-${i+1}`})));return data}}
function persist(){localStorage.setItem(STORAGE_KEY,JSON.stringify(store))}function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function money(v){return 'OMR '+Number(v||0).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:3})}function titleCase(s){return String(s||'').replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())}function statusClass(s){const x=String(s||'').toLowerCase();if(['active','paid','completed','won','resolved'].includes(x))return 'active';if(['overdue','lost','cancelled','inactive','rejected'].includes(x))return 'overdue';if(['in progress','issued','qualified','sent','confirmed','partially paid'].includes(x))return 'progress';if(['draft','on hold','void','snoozed'].includes(x))return 'hold';if(['planned','pending','open','proposal preparation','quotation sent','negotiation','acknowledged','medium'].includes(x))return 'pending';return 'hold'}function statusTag(s){return `<span class="status ${statusClass(s)}">${esc(s||'—')}</span>`}function fieldValue(key,val){if(['value','amount','total','paid'].includes(key)&&val!==''&&val!=null)return money(val);if(key==='progress')return `${esc(val||0)}%`;return esc(val||'—')}
let authMode='login';
function setAuthMode(mode){authMode=mode;const signup=mode==='signup';document.getElementById('showLogin').classList.toggle('active',!signup);document.getElementById('showSignup').classList.toggle('active',signup);document.getElementById('authNameWrap').hidden=!signup;document.getElementById('authName').required=signup;document.getElementById('authEyebrow').textContent=signup?'GET STARTED':'WELCOME BACK';document.getElementById('authTitle').textContent=signup?'Create your STS account':'Sign in to your workspace';document.getElementById('authSubtitle').textContent=signup?'Set up your local workspace account to get started.':'Enter your details to continue to your STS workspace.';document.getElementById('authSubmit').innerHTML=signup?'Create account <span>→</span>':'Sign in <span>→</span>';document.getElementById('authPassword').autocomplete=signup?'new-password':'current-password';document.getElementById('authError').textContent=''}
function setupAuth(){const existing=localStorage.getItem('sts-current-user');if(existing){try{activateWorkspace(JSON.parse(existing))}catch{localStorage.removeItem('sts-current-user')}}document.getElementById('showLogin').onclick=()=>setAuthMode('login');document.getElementById('showSignup').onclick=()=>setAuthMode('signup');document.getElementById('togglePassword').onclick=()=>{const input=document.getElementById('authPassword');input.type=input.type==='password'?'text':'password';document.getElementById('togglePassword').setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')};document.getElementById('authForm').onsubmit=e=>{e.preventDefault();const email=document.getElementById('authEmail').value.trim().toLowerCase(),password=document.getElementById('authPassword').value,name=document.getElementById('authName').value.trim();const users=JSON.parse(localStorage.getItem('sts-local-users')||'[]'),error=document.getElementById('authError');if(authMode==='signup'){if(!name){error.textContent='Please enter your name.';return}if(users.some(u=>u.email===email)){error.textContent='An account with this email already exists. Please sign in.';return}const user={name,email,password};users.push(user);localStorage.setItem('sts-local-users',JSON.stringify(users));const session={name,email};localStorage.setItem('sts-current-user',JSON.stringify(session));activateWorkspace(session);return}const user=users.find(u=>u.email===email&&u.password===password);if(!user){error.textContent='No matching local account was found. Create an account first, then sign in.';return}const session={name:user.name,email:user.email};localStorage.setItem('sts-current-user',JSON.stringify(session));activateWorkspace(session)}}
function activateWorkspace(user){document.getElementById('authScreen').hidden=true;document.getElementById('appShell').hidden=false;const name=user.name||user.email?.split('@')[0]||'STS User',initials=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();document.getElementById('profileName').textContent=name;document.getElementById('profileRole').textContent='Workspace user';document.getElementById('profileInitials').textContent=initials;document.getElementById('topInitials').textContent=initials}
function init(){setupAuth();renderNav();renderPage();document.getElementById('globalSearch').addEventListener('input',e=>{searchText=e.target.value; if(currentPage!=='Dashboard')renderPage()});document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'&&searchText.trim()){if(currentPage==='Dashboard')navigate('Clients & Contacts');else renderPage()}});document.getElementById('menuToggle').onclick=()=>toggleSidebar(true);document.getElementById('closeSidebar').onclick=()=>toggleSidebar(false);document.getElementById('scrim').onclick=()=>toggleSidebar(false);document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});document.getElementById('notificationBtn').onclick=toggleNotifications;document.getElementById('profileBtn').onclick=()=>navigate('My Profile');document.getElementById('topInitials').onclick=()=>navigate('My Profile');document.getElementById('topInitials').title='Open profile and account options';document.getElementById('topInitials').style.cursor='pointer';document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch').focus()}if(e.key==='Escape'){closeModal();closeNotifications()}})}
function renderNav(){let group='';let html='';NAV.forEach(([name,icon,g])=>{if(g!==group){if(group)html+='</div></div>';const expanded=group=== '' || currentPage==='Dashboard' || NAV.some(([n,,gr])=>gr===g&&n===currentPage);html+=`<div class="nav-group ${expanded?'':'collapsed'}"><button class="nav-group-toggle" type="button" aria-expanded="${expanded}"><span>${g.toUpperCase()}</span><span class="group-chevron">⌄</span></button><div class="nav-group-items">`;group=g}const label=name==='Dashboard'?'Overview':name;html+=`<button class="nav-item ${currentPage===name?'active':''}" data-page="${esc(name)}"><span class="nav-icon">${navIcon(icon)}</span><span>${esc(label)}</span>${name==='Alerts & Escalations'?`<span class="nav-count">${(store[name]||[]).filter(x=>x.status==='Open').length||2}</span>`:''}</button>`});html+='</div></div>';document.getElementById('mainNav').innerHTML=html;document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('.nav-group-toggle').forEach(b=>b.onclick=()=>{const groupEl=b.closest('.nav-group');groupEl.classList.toggle('collapsed');b.setAttribute('aria-expanded',String(!groupEl.classList.contains('collapsed')))})}
function navigate(page){currentPage=page;selectedRecord=null;statusFilter='All statuses';renderNav();renderPage();toggleSidebar(false);closeNotifications();window.scrollTo({top:0,behavior:'smooth'})}function toggleSidebar(show){document.getElementById('sidebar').classList.toggle('open',show);document.getElementById('scrim').classList.toggle('show',show)}
function pageHeading(title,desc,actions=''){return `<div class="page-heading"><div><p class="eyebrow">SMART TECHNICAL SERVICES</p><h1>${title}</h1><p class="page-subtitle">${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function renderPage(){document.getElementById('crumbCurrent').textContent=selectedRecord?'Record details':currentPage;const el=document.getElementById('pageContent');if(selectedRecord){el.innerHTML=renderDetail();bindDetail();return}if(currentPage==='My Profile'){el.innerHTML=renderProfile();bindProfile();return}if(currentPage==='Dashboard'){el.innerHTML=renderDashboard();bindDashboard()}else if(currentPage==='Reports & Analytics'){el.innerHTML=renderReports();bindReports()}else if(currentPage==='Settings'){el.innerHTML=renderSettings();bindSettings()}else{el.innerHTML=renderModule(currentPage);bindModule(currentPage)}}
function getCurrentUser(){try{return JSON.parse(localStorage.getItem('sts-current-user')||'{}')}catch{return {}}}
function renderProfile(){const u=getCurrentUser(),name=u.name||u.email?.split('@')[0]||'STS User',email=u.email||'Not provided',initials=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),created=(JSON.parse(localStorage.getItem('sts-local-users')||'[]').find(x=>x.email===email)||{}).createdAt;return `<div class="subpage-back-row"><button class="btn btn-back" data-profile-action="dashboard">${navIcon('arrow-left')}<span>Back to dashboard</span></button></div>${pageHeading('My Profile','Manage your account details, preferences and workspace access.')}<section class="profile-hero panel"><div class="profile-identity"><div class="profile-avatar-large">${esc(initials||'ST')}</div><div><p class="eyebrow">SIGNED IN ACCOUNT</p><h2>${esc(name)}</h2><p>${esc(email)}</p><span class="profile-status"><i></i> Active session</span></div></div><button class="btn btn-primary" data-profile-action="edit-name">✎ Edit profile</button></section><div class="profile-content-grid"><section class="panel"><div class="panel-head"><div><h3>Personal information</h3><p>Your details for this STS workspace</p></div></div><div class="panel-body"><div class="profile-info-grid"><div class="detail-field"><span>Full name</span><b>${esc(name)}</b></div><div class="detail-field"><span>Work email</span><b>${esc(email)}</b></div><div class="detail-field"><span>Account type</span><b>Workspace user</b></div><div class="detail-field"><span>Session status</span><b>${statusTag('Active')}</b></div></div><div id="profileEditArea"></div></div></section><section class="panel"><div class="panel-head"><div><h3>Account & preferences</h3><p>Common workspace options</p></div></div><div class="profile-options"><button class="profile-option" data-profile-action="preferences"><span class="profile-option-icon blue">${navIcon('settings-gear')}</span><span><b>Preferences</b><small>Workspace and display settings</small></span><span class="profile-option-arrow">›</span></button><button class="profile-option" data-profile-action="security"><span class="profile-option-icon teal"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg></span><span><b>Sign-in & security</b><small>Review your local account setup</small></span><span class="profile-option-arrow">›</span></button><button class="profile-option" data-profile-action="help"><span class="profile-option-icon mint"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M9.6 9a2.5 2.5 0 1 1 4.3 1.7c-1.1 1-1.9 1.2-1.9 2.8M12 17h.01"/></svg></span><span><b>Help & support</b><small>About the STS Operations Tracker</small></span><span class="profile-option-arrow">›</span></button><button class="profile-option signout-option" data-profile-action="signout"><span class="profile-option-icon red"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 17l5-5-5-5M15 12H4"/><path d="M12 4h5a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3h-5"/></svg></span><span><b>Sign out</b><small>End your current session on this browser</small></span><span class="profile-option-arrow">›</span></button></div></section></div><section class="panel profile-confirm-panel" id="profileConfirmPanel" hidden><div class="profile-confirm-copy"><span class="profile-option-icon red"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 17l5-5-5-5M15 12H4"/><path d="M12 4h5a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3h-5"/></svg></span><div><h3 id="profileConfirmTitle">Confirm action</h3><p id="profileConfirmText">Are you sure you want to continue?</p></div></div><div class="profile-confirm-actions"><button class="btn" data-profile-action="cancel-confirm">Cancel</button><button class="btn btn-primary" id="profileConfirmProceed">Continue</button></div></section><p class="helper-text" style="margin-top:14px">This front-end version stores account information in this browser only. For production, connect secure authentication and server-side account management.</p>`}
function bindProfile(){document.querySelectorAll('[data-profile-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.profileAction;if(action==='dashboard'){navigate('Dashboard');return}if(action==='edit-name'){const u=getCurrentUser(),area=document.getElementById('profileEditArea');area.innerHTML=`<form id="profileEditForm" class="profile-edit-form"><div class="form-field"><label for="profileEditName">Full name</label><input id="profileEditName" name="name" required value="${esc(u.name||'')}"></div><div class="form-actions"><button type="button" class="btn" id="cancelProfileEdit">Cancel</button><button type="submit" class="btn btn-primary">Save changes</button></div></form>`;document.getElementById('cancelProfileEdit').onclick=()=>area.innerHTML='';document.getElementById('profileEditForm').onsubmit=e=>{e.preventDefault();const name=document.getElementById('profileEditName').value.trim();if(!name)return;const user=getCurrentUser();user.name=name;localStorage.setItem('sts-current-user',JSON.stringify(user));const users=JSON.parse(localStorage.getItem('sts-local-users')||'[]');const idx=users.findIndex(x=>x.email===user.email);if(idx>=0){users[idx].name=name;localStorage.setItem('sts-local-users',JSON.stringify(users))}activateWorkspace(user);renderPage();toast('Profile updated','Your name has been updated in this browser.');};return}if(action==='preferences'){navigate('Settings');return}const panel=document.getElementById('profileConfirmPanel'),title=document.getElementById('profileConfirmTitle'),textNode=document.getElementById('profileConfirmText'),proceed=document.getElementById('profileConfirmProceed');if(action==='signout'){title.textContent='Sign out of Smart Technical Services?';textNode.textContent='You will return to the sign-in page. Your locally saved workspace records will remain in this browser.';panel.hidden=false;proceed.textContent='Sign out';proceed.onclick=signOut;panel.scrollIntoView({behavior:'smooth',block:'nearest'});return}if(action==='cancel-confirm'){panel.hidden=true;return}if(action==='security'){title.textContent='Sign-in & security';textNode.textContent='This preview stores credentials in browser storage and is intended for local testing only. Use a secure backend before using real company accounts.';panel.hidden=false;proceed.textContent='Got it';proceed.onclick=()=>panel.hidden=true;return}if(action==='help'){title.textContent='STS workspace help';textNode.textContent='Use the sidebar to open a module. Use the eye icon to view a record, the pencil icon to edit it, and My Profile to manage this account.';panel.hidden=false;proceed.textContent='Got it';proceed.onclick=()=>panel.hidden=true;return}})}
function signOut(){localStorage.removeItem('sts-current-user');document.getElementById('appShell').hidden=true;document.getElementById('authScreen').hidden=false;setAuthMode('login');document.getElementById('authForm').reset();document.getElementById('authError').textContent='';toast('Signed out','You have signed out of Smart Technical Services.');window.scrollTo({top:0,behavior:'smooth'})}
function getSignedInName(){try{const u=JSON.parse(localStorage.getItem('sts-current-user')||'{}');return (u.name||u.fullName||u.email||'there').split('@')[0]}catch{return 'there'}}
function getGreeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':h<21?'Good evening':'Good night'}
function renderDashboard(){const clients=store['Clients & Contacts'].length,leads=store['Leads & Opportunities'],projects=store.Projects,inv=store.Invoices,acts=store['Follow-ups & Activities'];const activeDeals=leads.filter(x=>!['Won','Lost'].includes(x.stage)).length;const due=acts.filter(x=>x.status==='Open'&&x.due<=today()).length;const outstanding=inv.reduce((s,x)=>s+Math.max(0,Number(x.total||0)-Number(x.paid||0)),0);const overdue=inv.filter(x=>x.status==='Overdue'||(x.due<today()&&Number(x.total||0)>Number(x.paid||0))).length;const won=leads.filter(x=>x.stage==='Won').length;return `${pageHeading('Operations Dashboard','Your business at a glance. Track sales, delivery and financial performance.','<select class="select-control" id="dateRange"><option>This month</option><option>This week</option><option>This quarter</option><option>This year</option></select><button class="btn btn-primary" data-action="quick-add">＋ Add new</button>')}
<div class="banner"><div class="banner-copy"><p class="eyebrow" style="color:#0A936A">${new Date().toLocaleDateString(undefined,{weekday:"long",day:"numeric",month:"long",year:"numeric"}).toUpperCase()}</p><h2>${getGreeting()}, ${esc(getSignedInName())} <span>✦</span></h2><p>Here is the latest pulse on your sales pipeline and project operations.</p></div><div class="banner-meta"><span class="online-dot"></span> All systems operational</div></div>
<div class="kpi-grid"><div class="kpi-card" data-goto="Clients & Contacts"><div class="kpi-top"><span class="kpi-label">Total clients</span><span class="kpi-icon">${navIcon('users-round')}</span></div><div class="kpi-value">${clients.toString().padStart(2,'0')}</div><div class="kpi-foot"><span class="trend">↗ 12%</span> vs last month</div></div><div class="kpi-card" data-goto="Leads & Opportunities"><div class="kpi-top"><span class="kpi-label">Active deals</span><span class="kpi-icon teal">${navIcon('target')}</span></div><div class="kpi-value">${activeDeals.toString().padStart(2,'0')}</div><div class="kpi-foot"><span class="trend">↗ 8.4%</span> pipeline activity</div></div><div class="kpi-card" data-goto="Projects"><div class="kpi-top"><span class="kpi-label">Active projects</span><span class="kpi-icon green">${navIcon('folder-kanban')}</span></div><div class="kpi-value">${projects.filter(p=>p.status==='In Progress').length.toString().padStart(2,'0')}</div><div class="kpi-foot">Across delivery teams</div></div><div class="kpi-card" data-goto="Follow-ups & Activities"><div class="kpi-top"><span class="kpi-label">Follow-ups due</span><span class="kpi-icon orange">${navIcon('calendar-clock')}</span></div><div class="kpi-value">${due.toString().padStart(2,'0')}</div><div class="kpi-foot">${acts.filter(x=>x.status==='Open'&&x.due<today()).length} overdue activities</div></div><div class="kpi-card" data-goto="Invoices"><div class="kpi-top"><span class="kpi-label">Outstanding</span><span class="kpi-icon purple">${navIcon('wallet-cards')}</span></div><div class="kpi-value" style="font-size:23px">${Number(outstanding).toLocaleString('en-US')}</div><div class="kpi-foot">OMR · ${overdue} overdue invoice${overdue===1?'':'s'}</div></div></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Sales performance</h3><p>Monthly deal value and won revenue</p></div><div class="chart-legend"><span><i class="legend-dot" style="background:#0A85EA"></i>Pipeline</span><span><i class="legend-dot" style="background:#0AA6A0"></i>Won</span></div></div><div class="panel-body"><div class="bar-chart">${[[35,16],[49,24],[44,18],[66,31],[54,25],[78,39],[60,28],[86,43],[73,35],[92,48],[80,40],[100,54]].map(([a,b])=>`<div class="bar-group"><div class="bar" style="height:${a}%"></div><div class="bar secondary" style="height:${b}%"></div></div>`).join('')}</div><div class="chart-labels"><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span><span>Nov</span><span>Dec</span></div><div class="mini-stat-row"><div class="mini-stat"><span>Pipeline value</span><b>${money(leads.filter(x=>!['Won','Lost'].includes(x.stage)).reduce((s,x)=>s+Number(x.value||0),0))}</b></div><div class="mini-stat"><span>Open opportunities</span><b>${activeDeals}</b></div><div class="mini-stat"><span>Conversion rate</span><b>${leads.length?Math.round(won/leads.length*100):0}%</b></div></div></div></section>
<section class="panel"><div class="panel-head"><div><h3>Opportunity pipeline</h3><p>Deals grouped by current stage</p></div><button class="btn" data-goto="Leads & Opportunities">View all ↗</button></div><div class="panel-body"><div class="pipeline-list">${[['New',leads.filter(x=>x.stage==='New').length,'#9DB3C6'],['Qualified',leads.filter(x=>x.stage==='Qualified').length,'#0A85EA'],['Quotation sent',leads.filter(x=>x.stage==='Quotation Sent').length,'#0082AA'],['Negotiation',leads.filter(x=>x.stage==='Negotiation').length,'#10B981'],['Won',won,'#7C67D9']].map(([n,c,color])=>`<div class="pipeline-row"><span class="pipeline-name">${n}</span><div class="pipeline-track"><div class="pipeline-fill" style="width:${Math.max(6,c/Math.max(leads.length,1)*100)}%;background:${color}"></div></div><b class="pipeline-count">${c}</b></div>`).join('')}</div><div class="inline-note">Keep every open deal connected to an owner and a dated next action.</div></div></section></div>
<div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h3>Priority follow-ups</h3><p>Activities that need your attention</p></div><button class="btn" data-goto="Follow-ups & Activities">View activities ↗</button></div>${renderTable('Follow-ups & Activities',acts.filter(x=>x.status==='Open').slice(0,4),true)}</section><section class="panel"><div class="panel-head"><div><h3>Recent activity</h3><p>Latest updates across the workspace</p></div><button class="btn" data-action="activity-log">Activity log</button></div><div class="panel-body"><div class="activity-list"><div class="activity-item"><span class="activity-icon">▤</span><div class="activity-copy"><b>Quotation sent to Al Noor Facilities</b><p>Sarah Johnson · QTN-2026-041</p></div><span class="activity-time">1h ago</span></div><div class="activity-item"><span class="activity-icon" style="background:#E3F8EF;color:#059669">⌂</span><div class="activity-copy"><b>Project milestone updated</b><p>AMC – Al Noor Facilities · 72% complete</p></div><span class="activity-time">3h ago</span></div><div class="activity-item"><span class="activity-icon" style="background:#FFF1E0;color:#C77713">＄</span><div class="activity-copy"><b>Payment received · OMR 2,000</b><p>Al Noor Facilities LLC · PAY-2026-036</p></div><span class="activity-time">Yesterday</span></div></div></div></section></div>
<div class="section-gap"><div class="panel-head" style="padding-left:0"><div><h3>Quick actions</h3><p>Jump straight into your most common workflows</p></div></div><div class="quick-links"><button class="quick-link" data-add="Clients & Contacts"><span>${navIcon('user-round-plus')}</span>Add client</button><button class="quick-link" data-add="Leads & Opportunities"><span>${navIcon('target')}</span>Create opportunity</button><button class="quick-link" data-add="Follow-ups & Activities"><span>${navIcon('calendar-clock')}</span>Schedule follow-up</button><button class="quick-link" data-add="Projects"><span>${navIcon('folder-plus')}</span>Create project</button></div></div>`}
function today(){return '2026-10-29'}
function renderModule(page){const cfg=CONFIG[page],rows=filteredRows(page);const actions=`<button class="btn" data-action="export">⇩ Export CSV</button>${cfg.fields.length?`<button class="btn btn-primary" data-action="add">＋ Add ${esc(cfg.singular.toLowerCase())}</button>`:''}`;let intro=pageHeading(page,cfg.desc,actions);if(page==='Invoices'){const missing=store.Projects.filter(p=>p.status==='In Progress'&&p.progress>=65).length;intro+=`<div class="inline-note"><b>Billing watch:</b> ${missing} active project milestone${missing===1?' is':'s are'} approaching billing readiness. Review billable work before the next close.</div>`}if(page==='Follow-ups & Activities'){intro+=`<div class="banner" style="padding:16px 20px;margin-bottom:17px"><div class="banner-copy"><h2 style="font-size:15px">Follow-up discipline keeps deals moving.</h2><p>Only completed client interactions update the Last Contacted date.</p></div><div class="banner-meta">↻ Activity workflow</div></div><div class="inline-note email-reminder-note"><span><b>Email triggers:</b> create an email draft for all open follow-ups due today or overdue.</span><button class="btn btn-primary" id="emailDueFollowups">✉ Email due follow-ups</button></div>`}if(page==='Projects'){intro+=`<div class="kpi-grid" style="grid-template-columns:repeat(3,minmax(0,1fr));margin-bottom:17px"><div class="kpi-card"><div class="kpi-label">Active projects</div><div class="kpi-value">${store[page].filter(x=>x.status==='In Progress').length}</div><div class="kpi-foot">Currently in delivery</div></div><div class="kpi-card"><div class="kpi-label">Average completion</div><div class="kpi-value">${Math.round(store[page].reduce((s,x)=>s+Number(x.progress||0),0)/Math.max(store[page].length,1))}%</div><div class="kpi-foot">Across all listed projects</div></div><div class="kpi-card"><div class="kpi-label">Portfolio budget</div><div class="kpi-value" style="font-size:23px">${store[page].reduce((s,x)=>s+Number(x.value||0),0).toLocaleString('en-US')}</div><div class="kpi-foot">OMR contract value</div></div></div>`}return `${intro}<section class="panel"><div class="module-toolbar"><div class="toolbar-left"><label class="search-field"><span>⌕</span><input id="moduleSearch" value="${esc(searchText)}" placeholder="Search ${esc(page.toLowerCase())}..."></label><select id="statusFilter" class="select-control"><option>All statuses</option>${[...new Set((store[page]||[]).map(r=>r.status||r.stage).filter(Boolean))].map(s=>`<option ${statusFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="toolbar-right"><button class="filter-chip" data-action="reset-filters">↺ Reset filters</button><button class="btn" data-action="export">⇩ Export</button></div></div>${renderTable(page,rows)}<div class="table-footer"><span>Showing <b>${rows.length}</b> of <b>${store[page].length}</b> records</span><div class="pagination"><button class="page-btn">‹</button><button class="page-btn active">1</button><button class="page-btn">›</button></div></div></section><p class="helper-text" style="margin-top:13px">Changes are saved in this browser for this prototype. Production authentication, database permissions and email automation require a connected backend.</p>`}
function filteredRows(page){let rows=store[page]||[];const q=searchText.trim().toLowerCase();if(q)rows=rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(q)));if(statusFilter!=='All statuses')rows=rows.filter(r=>(r.status||r.stage)===statusFilter);return rows}
function renderTable(page,rows,compact=false){const cfg=CONFIG[page];if(!cfg||!cfg.columns.length)return `<div class="empty-state"><div class="empty-icon">▤</div><h3>No records to display</h3><p>Records will appear here once you add them.</p></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr>${cfg.columns.map(([,label])=>`<th>${esc(label.toUpperCase())}</th>`).join('')}<th>ACTIONS</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cfg.columns.map(([key])=>`<td>${key==='status'||key==='stage'?statusTag(r[key]):key==='progress'?`<div style="display:flex;align-items:center;gap:8px;min-width:100px"><div class="pipeline-track" style="width:55px"><div class="pipeline-fill" style="width:${Math.min(100,Number(r[key]||0))}%"></div></div><b>${esc(r[key]||0)}%</b></div>`:key==='amount'||key==='total'||key==='paid'||key==='value'?`<span class="primary-cell">${fieldValue(key,r[key])}</span>`:key==='company'||key==='title'||key==='name'||key==='number'||key==='reference'||key==='code'?`<button class="record-link" data-record="${esc(r._id)}" data-record-page="${esc(page)}">${esc(r[key]||'—')}</button>`:`${esc(r[key]||'—')}`}</td>`).join('')}<td><div class="row-actions"><button class="row-action view-action" aria-label="View details" title="View details" data-record="${esc(r._id)}" data-record-page="${esc(page)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg></button><button class="row-action edit-action" aria-label="Edit record" title="Edit record" data-edit="${esc(r._id)}" data-edit-page="${esc(page)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg></button></div></td></tr>`).join(''):`<tr><td colspan="${cfg.columns.length+1}"><div class="empty-state"><div class="empty-icon">⌕</div><h3>No matching records</h3><p>Try changing your search or filters.</p></div></td></tr>`}</tbody></table></div>`}
function renderDetail(){const page=selectedRecord.page,r=selectedRecord.record,cfg=CONFIG[page];return `<div class="subpage-back-row"><button class="btn btn-back" data-action="back">${navIcon('arrow-left')}<span>Back to ${esc(detailBackPage)}</span></button></div>${pageHeading(r.name||r.company||r.title||r.number||r.reference||cfg.singular+' details',`${page} · Record overview`,`<button class="btn btn-primary" data-edit="${esc(r._id)}" data-edit-page="${esc(page)}"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg> Edit details</button>`)}<div class="detail-layout"><div><section class="panel"><div class="detail-hero"><div><p class="eyebrow">RECORD SUMMARY</p><h2>${esc(r.name||r.company||r.title||r.number||r.reference||cfg.singular)}</h2><p>${esc(r.client||r.email||r.description||'Global Chemicals LLC record')}</p></div>${statusTag(r.status||r.stage||'Active')}</div><div class="panel-head"><div><h3>Details</h3><p>Current saved record information</p></div></div><div class="panel-body"><div class="detail-grid">${Object.entries(r).filter(([k])=>k!=='_id').map(([k,v])=>`<div class="detail-field"><span>${esc(titleCase(k))}</span><b>${['status','stage'].includes(k)?statusTag(v):['value','amount','total','paid'].includes(k)?fieldValue(k,v):k==='progress'?`${esc(v)}%`:esc(v||'—')}</b></div>`).join('')}</div></div></section><section class="panel section-gap"><div class="panel-head"><div><h3>Activity history</h3><p>Recent updates related to this record</p></div></div><div class="panel-body"><div class="activity-list"><div class="activity-item"><span class="activity-icon">✎</span><div class="activity-copy"><b>Record available in workspace</b><p>Created and maintained in the local Global Chemicals tracker.</p></div><span class="activity-time">Today</span></div><div class="activity-item"><span class="activity-icon" style="background:#E3F8EF;color:#059669">✓</span><div class="activity-copy"><b>Access scope</b><p>In production, visibility is controlled by assigned role and record ownership.</p></div></div></div></div></section></div><aside><section class="panel"><div class="panel-head"><div><h3>Next actions</h3><p>Keep the workflow moving</p></div></div><div class="panel-body"><button class="btn btn-soft" style="width:100%;margin-bottom:9px" data-edit="${esc(r._id)}" data-edit-page="${esc(page)}"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg> Update details</button><button class="btn" style="width:100%;margin-bottom:9px" data-action="duplicate"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg> Duplicate record</button><button class="btn btn-danger" style="width:100%" data-action="delete"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="m19 6-1 14H6L5 6"/><path d="M10 11v5M14 11v5"/></svg> Delete record</button><p class="helper-text" style="margin-top:13px">Deleting a record is permanent in this browser. Confirm before proceeding.</p></div></section><section class="panel section-gap"><div class="panel-head"><div><h3>Record reference</h3><p>Internal identifier</p></div></div><div class="panel-body"><div class="detail-field"><span>Record ID</span><b>${esc(r._id)}</b></div><div class="detail-field"><span>Module</span><b>${esc(page)}</b></div><div class="detail-field"><span>Storage</span><b>Browser local storage</b></div></div></section></aside></div>`}
function bindDetail(){document.querySelectorAll('[data-action="back"]').forEach(b=>b.onclick=()=>{selectedRecord=null;currentPage=detailBackPage;renderNav();renderPage()});bindCommon();}
function emailDueFollowups(){const todayDate=today();const dueItems=(store['Follow-ups & Activities']||[]).filter(x=>x.status==='Open'&&x.due&&x.due<=todayDate);if(!dueItems.length){toast('No due follow-ups','There are no open follow-ups due today or overdue.');return}const settings=JSON.parse(localStorage.getItem('gcl-company-settings')||'{}');const recipient=(settings.reminderEmail||'').trim();const subject=encodeURIComponent(`Global Chemicals LLC — ${dueItems.length} due follow-up${dueItems.length===1?'':'s'}`);const body=encodeURIComponent(`Hello,\n\nThe following Global Chemicals LLC follow-ups are due today or overdue:\n\n${dueItems.map((x,i)=>`${i+1}. ${x.title}\n   Client: ${x.client}\n   Due: ${x.due}\n   Owner: ${x.owner}\n   Priority: ${x.priority||'Medium'}`).join('\n\n')}\n\nPlease review and update the activity status.\n\nGlobal Chemicals LLC Operations`);window.location.href=`mailto:${encodeURIComponent(recipient)}?subject=${subject}&body=${body}`;toast('Email draft prepared',`Prepared a reminder for ${dueItems.length} due follow-up${dueItems.length===1?'':'s'}. Send it from your email app.`)}

function bindModule(page){if(page==='Follow-ups & Activities'){const reminderBtn=document.getElementById('emailDueFollowups');if(reminderBtn)reminderBtn.onclick=emailDueFollowups;}const s=document.getElementById('moduleSearch');if(s)s.addEventListener('input',e=>{searchText=e.target.value;renderPage();const ns=document.getElementById('moduleSearch');ns.focus();ns.setSelectionRange(ns.value.length,ns.value.length)});const sf=document.getElementById('statusFilter');if(sf)sf.onchange=()=>{statusFilter=sf.value;renderPage()};bindCommon()}
function bindDashboard(){bindCommon();document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.getElementById('dateRange').onchange=e=>toast('Date range updated',`Dashboard range set to ${e.target.value.toLowerCase()}.`)}
function bindCommon(){document.querySelectorAll('[data-action="add"],[data-action="quick-add"]').forEach(b=>b.onclick=()=>openQuickAdd());document.querySelectorAll('[data-action="export"]').forEach(b=>b.onclick=()=>exportCSV(currentPage));document.querySelectorAll('[data-action="reset-filters"]').forEach(b=>b.onclick=()=>{searchText='';statusFilter='All statuses';renderPage()});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openRecord(b.dataset.recordPage,b.dataset.record));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(b.dataset.editPage,b.dataset.edit));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-action="back"]').forEach(b=>b.onclick=()=>{selectedRecord=null;currentPage=detailBackPage;renderPage()});document.querySelectorAll('[data-action="delete"]').forEach(b=>b.onclick=deleteRecord);document.querySelectorAll('[data-action="duplicate"]').forEach(b=>b.onclick=duplicateRecord);document.querySelectorAll('[data-action="activity-log"]').forEach(b=>b.onclick=()=>toast('Activity log','Recent workspace activity is shown on the dashboard.'))}
function openRecord(page,id){const r=(store[page]||[]).find(x=>x._id===id);if(!r)return;detailBackPage=currentPage;selectedRecord={page,record:r};renderPage();window.scrollTo({top:0,behavior:'smooth'})}
function openQuickAdd(){showModal('Choose a workflow','QUICK ACTION',`<p class="page-subtitle" style="margin-bottom:16px">What would you like to add to the workspace?</p><div class="quick-links" style="grid-template-columns:repeat(2,1fr)">${['Clients & Contacts','Leads & Opportunities','Follow-ups & Activities','Projects','Quotations','Invoices'].map(p=>`<button class="quick-link" data-modal-add="${esc(p)}"><span>${CONFIG[p].icon}</span>${esc(CONFIG[p].singular)}</button>`).join('')}</div>`);document.querySelectorAll('[data-modal-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.modalAdd))}
function openForm(page,id=null){const cfg=CONFIG[page];if(!cfg||!cfg.fields.length){closeModal();toast('Not available','This section does not have an entry form.');return}const old=id?(store[page]||[]).find(x=>x._id===id):null;showModal(old?`Edit ${cfg.singular.toLowerCase()}`:`Add ${cfg.singular.toLowerCase()}`,old?'EDIT RECORD':'NEW RECORD',formHTML(page,old));const form=document.getElementById('recordForm');form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),obj={};cfg.fields.forEach(([key,label,type,required,opts])=>obj[key]=fd.get(key)||'');if(old){Object.assign(old,obj);toast('Changes saved',`${cfg.singular} details have been updated.`)}else{obj._id=`${slug(page)}-${Date.now()}`;store[page].unshift(obj);toast('Record created',`${cfg.singular} has been added successfully.`)}persist();closeModal();selectedRecord=null;currentPage=page;renderNav();renderPage()};document.getElementById('cancelForm').onclick=closeModal}
function formHTML(page,old){const cfg=CONFIG[page];return `<form id="recordForm"><div class="form-grid">${cfg.fields.map(([key,label,type,required,opts])=>{const value=old?.[key]??'';let control='';if(type==='select')control=`<select name="${key}" ${required?'required':''}><option value="">Select ${esc(label.toLowerCase())}</option>${opts.map(o=>`<option ${String(value)===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea name="${key}" placeholder="Enter ${esc(label.toLowerCase())}">${esc(value)}</textarea>`;else control=`<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.001"':''} placeholder="${type==='date'?'Select date':'Enter '+esc(label.toLowerCase())}">`;return `<div class="form-field ${type==='textarea'?'full':''}"><label>${esc(label)}${required?' *':''}</label>${control}</div>`}).join('')}</div><div class="form-actions"><button type="button" class="btn" id="cancelForm">Cancel</button><button class="btn btn-primary" type="submit">${old?'Save changes':'Create record'} →</button></div></form>`}
function showModal(title,eyebrow,body){document.getElementById('modalTitle').textContent=title;document.getElementById('modalEyebrow').textContent=eyebrow;document.getElementById('modalBody').innerHTML=body;document.getElementById('modalBackdrop').hidden=false;document.body.style.overflow='hidden'}function closeModal(){document.getElementById('modalBackdrop').hidden=true;document.body.style.overflow=''}
function deleteRecord(){if(!selectedRecord)return;const {page,record}=selectedRecord;if(!confirm(`Delete this ${CONFIG[page].singular.toLowerCase()}? This cannot be undone.`))return;store[page]=store[page].filter(x=>x._id!==record._id);persist();selectedRecord=null;currentPage=page;renderPage();toast('Record deleted','The record was removed from this browser.')}
function duplicateRecord(){if(!selectedRecord)return;const {page,record}=selectedRecord;const copy={...record,_id:`${slug(page)}-${Date.now()}`};const firstKey=CONFIG[page].fields[0]?.[0];if(firstKey&&copy[firstKey])copy[firstKey]+=' (Copy)';store[page].unshift(copy);persist();selectedRecord={page,record:copy};renderPage();toast('Record duplicated','A copy has been created.')}
function exportCSV(page){const rows=store[page]||[];if(!rows.length){toast('Nothing to export','There are no records in this module yet.');return}const keys=[...new Set(rows.flatMap(r=>Object.keys(r).filter(k=>k!=='_id')))];const csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`sts-${slug(page)}.csv`;a.click();URL.revokeObjectURL(url);toast('Export ready',`${rows.length} records exported as CSV.`)}
function toast(title,msg){const t=document.createElement('div');t.className='toast';t.innerHTML=`<span>✓</span><b>${esc(title)}</b><div style="margin:5px 0 0 22px;color:#C4D4E2">${esc(msg)}</div>`;document.getElementById('toastRegion').appendChild(t);setTimeout(()=>t.remove(),3500)}
function toggleNotifications(){const existing=document.getElementById('noticePanel');if(existing){existing.remove();return}const alerts=store['Alerts & Escalations'].filter(a=>a.status==='Open');const p=document.createElement('div');p.className='notice-panel';p.id='noticePanel';p.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center"><h3>Notifications</h3><button class="icon-btn" id="closeNotices">×</button></div><p class="helper-text" style="margin:6px 0 3px">${alerts.length} items need attention</p>${alerts.slice(0,4).map(a=>`<div class="notice-row"><span class="notice-dot"></span><div><b>${esc(a.title)}</b><p>${esc(a.trigger)} · ${esc(a.owner)} · ${esc(a.due||'No due date')}</p></div></div>`).join('')||'<p class="helper-text">You are all caught up.</p>'}<button class="btn btn-soft" style="width:100%;margin-top:10px" id="viewAlerts">View all alerts</button>`;document.body.appendChild(p);document.getElementById('closeNotices').onclick=closeNotifications;document.getElementById('viewAlerts').onclick=()=>{closeNotifications();navigate('Alerts & Escalations')}}function closeNotifications(){document.getElementById('noticePanel')?.remove()}
function renderReports(){return `${pageHeading('Reports & Analytics','Understand sales performance, delivery health and financial exposure.','<button class="btn btn-primary" data-action="export">⇩ Export current data</button>')}<div class="kpi-grid" style="grid-template-columns:repeat(4,minmax(0,1fr))"><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Pipeline value</span><span class="kpi-icon">◈</span></div><div class="kpi-value" style="font-size:23px">${money(store['Leads & Opportunities'].filter(x=>!['Won','Lost'].includes(x.stage)).reduce((s,x)=>s+Number(x.value||0),0))}</div><div class="kpi-foot">Open opportunities</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Contract value</span><span class="kpi-icon teal">${navIcon('file-check')}</span></div><div class="kpi-value" style="font-size:23px">${money(store.Projects.reduce((s,x)=>s+Number(x.value||0),0))}</div><div class="kpi-foot">Project portfolio</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Collected</span><span class="kpi-icon green">${navIcon('wallet')}</span></div><div class="kpi-value" style="font-size:23px">${money(store['Payments & Collections'].reduce((s,x)=>s+Number(x.amount||0),0))}</div><div class="kpi-foot">Recorded receipts</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Overdue invoices</span><span class="kpi-icon orange">${navIcon('alert-triangle')}</span></div><div class="kpi-value">${store.Invoices.filter(x=>x.status==='Overdue').length}</div><div class="kpi-foot">Need collection action</div></div></div><div class="dashboard-grid section-gap"><section class="panel"><div class="panel-head"><div><h3>Available reports</h3><p>Open a module report or export its current data.</p></div></div><div class="panel-body"><div class="activity-list">${[['Employee Sales Performance','Leads & Opportunities','Deal values, owners and stage conversion'],['Client Contact Report','Follow-ups & Activities','Due, overdue and completed customer interactions'],['Project Delivery Report','Projects','Project status, target dates and progress'],['Invoice Aging Report','Invoices','Invoice totals, due dates and outstanding amounts'],['Collections Report','Payments & Collections','Recorded receipts and payment methods']].map(([name,p,desc])=>`<div class="activity-item"><span class="activity-icon">▥</span><div class="activity-copy"><b>${name}</b><p>${desc}</p></div><button class="btn" data-goto="${p}">Open ↗</button></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h3>Invoice aging overview</h3><p>Outstanding balances by status</p></div></div><div class="panel-body"><div class="pipeline-list">${[['Paid',store.Invoices.filter(x=>x.status==='Paid').length,'#10B981'],['Partially paid',store.Invoices.filter(x=>x.status==='Partially Paid').length,'#0A85EA'],['Overdue',store.Invoices.filter(x=>x.status==='Overdue').length,'#F97316'],['Issued',store.Invoices.filter(x=>x.status==='Issued').length,'#0082AA']].map(([n,c,color])=>`<div class="pipeline-row"><span class="pipeline-name">${n}</span><div class="pipeline-track"><div class="pipeline-fill" style="width:${Math.max(c?12:0,c/Math.max(store.Invoices.length,1)*100)}%;background:${color}"></div></div><b class="pipeline-count">${c}</b></div>`).join('')}</div><div class="inline-note">Exports from this static version are CSV. PDF and Excel report generation can be added with a backend.</div></div></section></div>`}
function bindReports(){bindCommon();document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto))}
function renderSettings(){return `${pageHeading('Settings','Manage workspace preferences and prepare for future integrations.','<button class="btn btn-primary" id="saveSettings">Save preferences</button>')}<div class="detail-layout"><div><section class="panel"><div class="panel-head"><div><h3>Company profile</h3><p>Organization details used across your workspace</p></div></div><div class="panel-body"><form id="settingsForm"><div class="form-grid"><div class="form-field"><label>Company name</label><input name="company" value="Global Chemicals LLC"></div><div class="form-field"><label>Default currency</label><select name="currency"><option>OMR — Omani Rial</option><option>INR — Indian Rupee</option><option>USD — US Dollar</option></select></div><div class="form-field"><label>Timezone</label><select name="timezone"><option>Asia/Muscat</option><option>Asia/Kolkata</option><option>UTC</option></select></div><div class="form-field"><label>Date format</label><select name="date"><option>DD MMM YYYY</option><option>YYYY-MM-DD</option><option>MM/DD/YYYY</option></select></div><div class="form-field full"><label>Company email</label><input type="email" name="email" placeholder="operations@globalchemicals.com"></div><div class="form-field full"><label>Due follow-up reminder recipient</label><input type="email" name="reminderEmail" id="reminderEmail" placeholder="sales.manager@globalchemicals.com"><small class="helper-text">Used as the recipient when you prepare due-follow-up reminder emails.</small></div></div><div class="form-actions"><button type="submit" class="btn btn-primary">Save company settings</button></div></form></div></section><section class="panel section-gap"><div class="panel-head"><div><h3>Reminder rules</h3><p>Suggested defaults from the requirements document</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>TRIGGER</th><th>FIRST REMINDER</th><th>ESCALATION</th></tr></thead><tbody><tr><td>Missed follow-up</td><td>Next day</td><td>Manager after 2 more days</td></tr><tr><td>Quotation unanswered</td><td>After 7 days</td><td>Manager after 10 days</td></tr><tr><td>Invoice not raised</td><td>3 days after billable date</td><td>Accounts Manager after 5 days</td></tr><tr><td>Invoice unpaid</td><td>1 day after due date</td><td>Manager after 7 days</td></tr></tbody></table></div></section></div><div><section class="panel"><div class="panel-head"><div><h3>Integration readiness</h3><p>Future connections</p></div></div><div class="panel-body"><div class="activity-item"><span class="activity-icon">${navIcon('workflow')}</span><div class="activity-copy"><b>Zoho CRM</b><p>Planned for a future phase</p></div>${statusTag('On hold')}</div><div class="activity-item"><span class="activity-icon" style="background:#E3F8EF;color:#059669">${navIcon('book-open')}</span><div class="activity-copy"><b>Zoho Books</b><p>Invoice and payment synchronization</p></div>${statusTag('On hold')}</div><div class="inline-note">This version uses browser local storage only. Do not enter confidential or production customer information.</div></div></section><section class="panel section-gap"><div class="panel-head"><div><h3>Data management</h3><p>Local prototype controls</p></div></div><div class="panel-body"><button class="btn" id="downloadBackup" style="width:100%;margin-bottom:9px">⇩ Download JSON backup</button><button class="btn btn-danger" id="resetData" style="width:100%">Reset sample data</button><p class="helper-text" style="margin-top:12px">Reset restores the initial sample records and removes changes saved in this browser.</p></div></section></div></div>`}
function bindSettings(){bindCommon();const savedCompanySettings=JSON.parse(localStorage.getItem('gcl-company-settings')||'{}');const reminderInput=document.getElementById('reminderEmail');if(reminderInput)reminderInput.value=savedCompanySettings.reminderEmail||'';document.getElementById('settingsForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);localStorage.setItem('gcl-company-settings',JSON.stringify({company:fd.get('company'),email:fd.get('email'),reminderEmail:fd.get('reminderEmail'),currency:fd.get('currency'),timezone:fd.get('timezone'),date:fd.get('date')}));toast('Settings saved','Company and reminder preferences saved in this browser.');};document.getElementById('saveSettings').onclick=()=>document.getElementById('settingsForm').requestSubmit();document.getElementById('downloadBackup').onclick=()=>{const blob=new Blob([JSON.stringify(store,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='global-chemicals-operations-backup.json';a.click();URL.revokeObjectURL(url);toast('Backup downloaded','Your local workspace data has been exported.')};document.getElementById('resetData').onclick=()=>{if(!confirm('Reset all local records to the original sample data?'))return;localStorage.removeItem(STORAGE_KEY);store=loadStore();renderNav();renderPage();toast('Sample data restored','Workspace data was reset.')}}
init();
